def is_valid_ipv4(s: str) -> bool:
    """Return True if s is a dotted-decimal IPv4 address: exactly four parts
    separated by '.', each part made only of digits, with a value from 0 to 255
    and no leading zeros (except the single digit '0').
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        try:
            num = int(part)
            if num < 0 or num > 255:
                return False
        except ValueError:
            return False
    return True
