def balanced_brackets(s: str) -> bool:
    """Return True if every (, [ and { in s is closed by the matching bracket in the correct order. Ignore all other characters."""
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}
    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
    return not stack
```
