def longest_common_prefix(strs: list[str]) -> str:
    """
    Return the longest string that is a prefix of every string in strs.
    Return '' for an empty list.
    """
    if not strs:
        return ""

    prefix = strs[0]
    for i in range(1, len(strs)):
        while strs[i].find(prefix) != 0:
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix
```
