def factorial(n: int) -> int:
    """Return n! for a non-negative integer n, with 0! = 1.
    Raise ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result
