def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, the binary operators + - * /, parentheses, and spaces.
    * and / bind tighter than + and -, and operators of equal precedence associate left to right.
    Integer division truncates toward zero. Do not use eval or exec.
    """

    def tokenize(expr: str) -> list[str]:
        tokens = []
        current_num = ""
        for char in expr:
            if char.isdigit():
                current_num += char
            elif char in "+-*/() ":
                if current_num:
                    tokens.append(current_num)
                    current_num = ""
                if char.strip():
                    tokens.append(char)
            else:
                raise ValueError(f"Invalid character: {char}")
        if current_num:
            tokens.append(current_num)
        return tokens

    def precedence(op: str) -> int:
        if op in "+-":
            return 1
        if op in "*/":
            return 2
        return 0

    def apply_op(op: str, val2: int, val1: int) -> int:
        if op == "+":
            return val1 + val2
        if op == "-":
            return val1 - val2
        if op == "*":
            return val1 * val2
        if op == "/":
            return val1 // val2  # Integer division
        return 0

    tokens = tokenize(expr)
    values = []
    ops = []

    for token in tokens:
        if token.isdigit():
            values.append(int(token))
        elif token == "(":
            ops.append(token)
        elif token == ")":
            while ops and ops[-1] != "(":
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.pop()  # Pop the "("
        elif token in "+-*/":
            while ops and ops[-1] != "(" and precedence(ops[-1]) >= precedence(token):
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.append(token)

    while ops:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        values.append(apply_op(op, val2, val1))

    return values[0]
