def n_queens(n: int) -> int:
    """
    Return the number of ways to place n non-attacking queens on an n x n chessboard.
    n is between 1 and 10.
    """
    def is_safe(board, row, col):
        # Check same column
        for i in range(row):
            if board[i] == col:
                return False

        # Check upper left diagonal
        for i, j in zip(range(row - 1, -1, -1), range(col - 1, -1, -1)):
            if board[i] == j:
                return False

        # Check upper right diagonal
        for i, j in zip(range(row - 1, -1, -1), range(col + 1, n)):
            if board[i] == j:
                return False

        return True

    def solve_nqueens_util(board, row):
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                count += solve_nqueens_util(board, row + 1)
        return count

    board = [0] * n
    return solve_nqueens_util(board, 0)
