def rle_encode(s: str) -> str:
    """Run-length encode s by writing each maximal run of a repeated character as the character followed by its run length, e.g. 'aaabcc' -> 'a3b1c2'. Return '' for ''.
    """
    if not s:
        return ''

    encoded = ''
    count = 1
    for i in range(len(s)):
        if i + 1 < len(s) and s[i] == s[i + 1]:
            count += 1
        else:
            encoded += s[i] + str(count)
            count = 1
    return encoded
