def evaluate(expr: str) -> int:
    """
    Evaluate an arithmetic expression containing non-negative integers, the binary operators + - * /, parentheses, and spaces.
    * and / bind tighter than + and -, and operators of equal precedence associate left to right.
    Integer division truncates toward zero. Do not use eval or exec.
    """

    tokens = expr.split()
    tokens = [token for token in tokens if token != '']

    def precedence(token):
        if token in ('*', '/'):
            return 2
        elif token in ('+', '-'):
            return 1
        else:
            return 0

    def apply_op(op, val2, val1):
        if op == '+':
            return val1 + val2
        elif op == '-':
            return val1 - val2
        elif op == '*':
            return val1 * val2
        elif op == '/':
            return val1 // val2
        else:
            return 0

    values = []
    ops = []

    i = 0
    while i < len(tokens):
        token = tokens[i]

        if token.isdigit():
            values.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.pop()  # Pop the '('
        elif token in ('+', '-', '*', '/'):
            while ops and precedence(ops[-1]) >= precedence(token):
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.append(token)
        i += 1

    while ops:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        values.append(apply_op(op, val2, val1))

    return values[0]
