def topo_sort(n: int, edges: list[tuple[int, int]]) -> list[int]:
    """
    Nodes are 0..n-1 and each edge (u, v) means u must come before v.
    Return the lexicographically smallest topological ordering of all nodes, or [] if the graph contains a cycle.
    """
    in_degree = [0] * n
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        queue.sort()  # Lexicographically smallest
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return []  # Cycle detected
    else:
        return result
