    def precedence(op):
        if op in ("+", "-"):
            return 1
        elif op in ("*", "/"):
            return 2
        else:
            return 0

    def apply_op(op, val2, val1):
        if op == "+":
            return val1 + val2
        elif op == "-":
            return val1 - val2
        elif op == "*":
            return val1 * val2
        elif op == "/":
            return val1 // val2
        else:
            raise ValueError(f"Invalid operator: {op}")

