def lis_length(nums: list[int]) -> int:
    """Return the length of the longest strictly increasing subsequence of nums.
    The solution must handle 10^5 elements in well under one second, so it needs O(n log n) time.
    """
    tails = []
    for num in nums:
        if not tails or num > tails[-1]:
            tails.append(num)
        else:
            # Find the smallest tail that is greater than or equal to num
            l, r = 0, len(tails) - 1
            while l <= r:
                mid = (l + r) // 2
                if tails[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            tails[l] = num
    return len(tails)
