def min_window(s: str, t: str) -> str:
    """
    Return the shortest contiguous substring of s that contains every character of t,
    including repeated characters at least as many times as they appear in t.
    If several qualify, return the leftmost.
    Return '' if none exists or t is empty.
    """
    if not t:
        return ""

    t_freq = {}
    for char in t:
        t_freq[char] = t_freq.get(char, 0) + 1

    window_freq = {}
    left = 0
    right = 0
    matched = 0
    min_len = float('inf')
    min_start = 0

    while right < len(s):
        right_char = s[right]
        if right_char in t_freq:
            window_freq[right_char] = window_freq.get(right_char, 0) + 1
            if window_freq[right_char] == t_freq[right_char]:
                matched += 1

        while matched == len(t_freq):
            if right - left + 1 < min_len:
                min_len = right - left + 1
                min_start = left

            left_char = s[left]
            if left_char in t_freq:
                window_freq[left_char] -= 1
                if window_freq[left_char] < t_freq[left_char]:
                    matched -= 1

            left += 1

        right += 1

    if min_len == float('inf'):
        return ""
    else:
        return s[min_start:min_start + min_len]
