    for u, v in edges:
        in_degree[v] += 1
        graph[u].append(v)

    queue = []
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        queue.sort()  # Lexicographically smallest
        u = queue.pop(0)
        result.append(u)

        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != n:
        return []  # Cycle detected
    else:
        return result
