def evaluate(expr: str) -> int:
    """Evaluate an arithmetic expression containing non-negative integers, the binary operators + - * /, parentheses, and spaces.
    * and / bind tighter than + and -, and operators of equal precedence associate left to right.
    Integer division truncates toward zero. Do not use eval or exec.
    """

    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isspace():
                i += 1
            elif expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(int(expr[i:j]))
                i = j
            elif expr[i] in "+-*/()":
                tokens.append(expr[i])
                i += 1
            else:
                raise ValueError(f"Invalid character: {expr[i]}")
        return tokens

    def precedence(op):
        if op in "+-":
            return 1
        if op in "*/":
            return 2
        return 0

    def apply_op(op, val2, val1):
        if op == "+":
            return val1 + val2
        if op == "-":
            return val1 - val2
        if op == "*":
            return val1 * val2
        if op == "/":
            return val1 // val2
        return 0

    tokens = tokenize(expr)
    values = []
    ops = []

    for token in tokens:
        if isinstance(token, int):
            values.append(token)
        elif token == "(":
            ops.append(token)
        elif token == ")":
            while ops and ops[-1] != "(":
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.pop()  # Pop the "("
        elif token in "+-*/":
            while ops and precedence(ops[-1]) >= precedence(token):
                val2 = values.pop()
                val1 = values.pop()
                op = ops.pop()
                values.append(apply_op(op, val2, val1))
            ops.append(token)

    while ops:
        val2 = values.pop()
        val1 = values.pop()
        op = ops.pop()
        values.append(apply_op(op, val2, val1))

    return values[0]
